  ('book-the-lean-startup', 'The Lean Startup', 'Eric Ries', 'An original SentenceStep summary of Eric Ries'' methodology for building startups through rapid experimentation, validated learning, and a build-measure-learn loop instead of guessing what customers want', 2, false, true, 'published', 19),
