insert into book_sections (id, book_id, order_index, title, description) values
  ('book-the-lean-startup-sec1', 'book-the-lean-startup', 1, 'Why Most Startups Fail', 'Ries'' core claim: startups fail from building the wrong thing, not building it badly'),
