  ('book-the-lean-startup-sec3', 'book-the-lean-startup', 3, 'The Minimum Viable Product', 'The smallest experiment that still teaches something real'),
  ('book-the-lean-startup-sec4', 'book-the-lean-startup', 4, 'Validated Learning', 'Measuring progress by what you''ve actually proven, not by activity'),
  ('book-the-lean-startup-sec5', 'book-the-lean-startup', 5, 'Actionable Metrics vs Vanity Metrics', 'Numbers tied to a real, controllable cause versus numbers that just look good'),
  ('book-the-lean-startup-sec6', 'book-the-lean-startup', 6, 'The Pivot', 'Why changing direction is a normal, expected part of the process'),
  ('book-the-lean-startup-sec7', 'book-the-lean-startup', 7, 'Innovation Accounting', 'Turning vague optimism into concrete, testable milestones'),
  ('book-the-lean-startup-sec8', 'book-the-lean-startup', 8, 'Small Batches', 'Why releasing tiny changes often beats releasing big ones'),
  ('book-the-lean-startup-sec9', 'book-the-lean-startup', 9, 'Building an Adaptive Organization', 'Why the method is a way of running a company, not just launching one'),
  ('book-steve-jobs-sec1', 'book-steve-jobs', 1, 'An Adopted Child With Big Questions', 'Jobs'' early life, his adoption, and an intensity that unsettled his teachers'),
