  ('book-steve-jobs-sec4', 'book-steve-jobs', 4, 'Reality Distortion Field', 'The intensity that produced extraordinary results and exhausted people around him'),
  ('book-steve-jobs-sec5', 'book-steve-jobs', 5, 'Exile From Apple', 'Losing his own company, and the quiet years that reshaped his thinking'),
  ('book-steve-jobs-sec6', 'book-steve-jobs', 6, 'Pixar and a Different Kind of Storytelling', 'A second identity built on patience and long-term creative investment'),
  ('book-steve-jobs-sec7', 'book-steve-jobs', 7, 'The Return to Apple', 'Coming back to a struggling company and radically simplifying it'),
  ('book-steve-jobs-sec8', 'book-steve-jobs', 8, 'iPod, iPhone, and Reinventing Industries', 'Products that didn''t just sell well but reshaped entire industries'),
  ('book-steve-jobs-sec9', 'book-steve-jobs', 9, 'Perfectionism as Both Gift and Cost', 'The uncompromising nature that produced beloved products and strained relationships'),
  ('book-steve-jobs-sec10', 'book-steve-jobs', 10, 'A Legacy Built on Intersection', 'Technology and the liberal arts, and a legacy weighed against real personal flaws'),
  ('book-guns-germs-and-steel-sec1', 'book-guns-germs-and-steel', 1, 'Yali''s Question', 'The simple question that launched Diamond''s search for an honest answer'),
  ('book-guns-germs-and-steel-sec2', 'book-guns-germs-and-steel', 2, 'The Head Start of Farming', 'Why a handful of regions got an early agricultural advantage'),
  ('book-guns-germs-and-steel-sec3', 'book-guns-germs-and-steel', 3, 'Domesticable Animals', 'Why only a handful of large mammals could ever be domesticated at all'),
  ('book-guns-germs-and-steel-sec4', 'book-guns-germs-and-steel', 4, 'Continental Axes', 'How the shape of a continent quietly decided how fast crops could spread'),
  ('book-guns-germs-and-steel-sec5', 'book-guns-germs-and-steel', 5, 'Germs as an Unintended Weapon', 'How disease, not weapons, decided the outcome of entire conquests'),
  ('book-guns-germs-and-steel-sec6', 'book-guns-germs-and-steel', 6, 'Writing and the Spread of Knowledge', 'Why so few societies ever invented writing completely from scratch'),
  ('book-guns-germs-and-steel-sec7', 'book-guns-germs-and-steel', 7, 'From Villages to States', 'The rough path from small bands to organized, centralized states'),
  ('book-guns-germs-and-steel-sec8', 'book-guns-germs-and-steel', 8, 'Steel and the Tools of Conquest', 'How access to metal ore closed the loop of guns, germs, and steel'),
