  ('book-outliers-sec2', 'book-outliers', 2, 'The 10,000 Hour Rule', 'Why mastery needs both real ability and thousands of hours of rare opportunity'),
  ('book-outliers-sec3', 'book-outliers', 3, 'The Trouble With Geniuses', 'Why being merely smart enough, plus the right social skills, often wins'),
  ('book-outliers-sec4', 'book-outliers', 4, 'The Importance of Where You''re From', 'How family background quietly teaches children different scripts for confidence'),
