insert into book_sentences (id, section_id, order_index, en) values
  ('book-the-lean-startup-sec1-s1', 'book-the-lean-startup-sec1', 1, 'Most startups fail not because they build a bad product but because they build something nobody actually wants'),
  ('book-the-lean-startup-sec1-s2', 'book-the-lean-startup-sec1', 2, 'Founders often spend months perfecting a plan before ever testing it against a real customer'),
  ('book-the-lean-startup-sec1-s3', 'book-the-lean-startup-sec1', 3, 'Ries argues that a startup is fundamentally an experiment not a smaller version of a big company'),
  ('book-the-lean-startup-sec1-s4', 'book-the-lean-startup-sec1', 4, 'Traditional business planning assumes a stable market that a young startup rarely actually has'),
  ('book-the-lean-startup-sec1-s5', 'book-the-lean-startup-sec1', 5, 'The real danger is building something efficiently that turns out to be entirely the wrong thing'),
  ('book-the-lean-startup-sec2-s1', 'book-the-lean-startup-sec2', 1, 'Ries proposes a simple repeating cycle called build measure learn'),
  ('book-the-lean-startup-sec2-s2', 'book-the-lean-startup-sec2', 2, 'A team builds a small piece of the product measures how real customers respond then learns from the result'),
  ('book-the-lean-startup-sec2-s3', 'book-the-lean-startup-sec2', 3, 'Each loop should be completed as quickly as possible rather than perfected before release'),
  ('book-the-lean-startup-sec2-s4', 'book-the-lean-startup-sec2', 4, 'Speed through this loop matters more than the size or polish of any single version'),
  ('book-the-lean-startup-sec2-s5', 'book-the-lean-startup-sec2', 5, 'Startups that loop faster than competitors gain a genuine learning advantage over time'),
  ('book-the-lean-startup-sec3-s1', 'book-the-lean-startup-sec3', 1, 'A minimum viable product is the smallest version of an idea that still teaches something real'),
  ('book-the-lean-startup-sec3-s2', 'book-the-lean-startup-sec3', 2, 'It is not a low-quality product but a deliberately limited experiment'),
  ('book-the-lean-startup-sec3-s3', 'book-the-lean-startup-sec3', 3, 'Ries describes early MVPs that were barely more than a landing page or a manual process'),
  ('book-the-lean-startup-sec3-s4', 'book-the-lean-startup-sec3', 4, 'The goal is gathering real evidence not impressing early users with polish'),
  ('book-the-lean-startup-sec3-s5', 'book-the-lean-startup-sec3', 5, 'Many founders resist releasing something so incomplete fearing it will damage their reputation'),
  ('book-the-lean-startup-sec4-s1', 'book-the-lean-startup-sec4', 1, 'Progress in a startup should be measured by validated learning not by activity or output'),
  ('book-the-lean-startup-sec4-s2', 'book-the-lean-startup-sec4', 2, 'A team can stay extremely busy while learning almost nothing useful about its customers'),
  ('book-the-lean-startup-sec4-s3', 'book-the-lean-startup-sec4', 3, 'Validated learning means testing a specific hypothesis and honestly recording what happened'),
  ('book-the-lean-startup-sec4-s4', 'book-the-lean-startup-sec4', 4, 'Vanity metrics like total signups can rise while the underlying business quietly fails'),
  ('book-the-lean-startup-sec4-s5', 'book-the-lean-startup-sec4', 5, 'Ries insists founders track numbers that actually predict future customer behavior'),
  ('book-the-lean-startup-sec5-s1', 'book-the-lean-startup-sec5', 1, 'Vanity metrics look impressive on a slide but rarely explain what caused them to change'),
  ('book-the-lean-startup-sec5-s2', 'book-the-lean-startup-sec5', 2, 'Actionable metrics are tied clearly to a specific cause the team can influence directly'),
  ('book-the-lean-startup-sec5-s3', 'book-the-lean-startup-sec5', 3, 'Ries recommends cohort analysis tracking how each group of new users behaves over time'),
  ('book-the-lean-startup-sec5-s4', 'book-the-lean-startup-sec5', 4, 'This approach reveals whether real product changes are actually improving customer behavior'),
  ('book-the-lean-startup-sec5-s5', 'book-the-lean-startup-sec5', 5, 'Founders who chase vanity metrics often celebrate growth that never becomes a real business'),
  ('book-the-lean-startup-sec6-s1', 'book-the-lean-startup-sec6', 1, 'A pivot is a structured change in strategy while keeping what has already been validated'),
  ('book-the-lean-startup-sec6-s2', 'book-the-lean-startup-sec6', 2, 'Ries argues that pivoting is not failure but a normal expected part of building something new'),
  ('book-the-lean-startup-sec6-s3', 'book-the-lean-startup-sec6', 3, 'Teams that never consider pivoting often keep pouring resources into a proven dead end'),
  ('book-the-lean-startup-sec6-s4', 'book-the-lean-startup-sec6', 4, 'Common pivots include changing the target customer the core feature or the entire business model'),
  ('book-the-lean-startup-sec6-s5', 'book-the-lean-startup-sec6', 5, 'Recognizing the right moment to pivot depends on honestly reviewing the loop''s own data'),
  ('book-the-lean-startup-sec7-s1', 'book-the-lean-startup-sec7', 1, 'Ries proposes innovation accounting a way to measure progress inside deep uncertainty'),
  ('book-the-lean-startup-sec7-s2', 'book-the-lean-startup-sec7', 2, 'Traditional accounting assumes a predictable business which an early startup rarely has'),
  ('book-the-lean-startup-sec7-s3', 'book-the-lean-startup-sec7', 3, 'Instead teams set a baseline then test specific changes meant to move it in one direction'),
  ('book-the-lean-startup-sec7-s4', 'book-the-lean-startup-sec7', 4, 'This turns vague optimism into a series of concrete falsifiable experiments'),
  ('book-the-lean-startup-sec7-s5', 'book-the-lean-startup-sec7', 5, 'Investors and teams can then judge progress by real evidence instead of by confident storytelling'),
  ('book-the-lean-startup-sec8-s1', 'book-the-lean-startup-sec8', 1, 'Ries borrows the idea of small batch production from lean manufacturing'),
  ('book-the-lean-startup-sec8-s2', 'book-the-lean-startup-sec8', 2, 'Releasing tiny changes frequently surfaces problems faster than releasing large batches rarely'),
