  ('book-the-lean-startup-sec8-s5', 'book-the-lean-startup-sec8', 5, 'Teams working in small batches can also change direction far more quickly when needed'),
  ('book-the-lean-startup-sec9-s1', 'book-the-lean-startup-sec9', 1, 'The Lean Startup is not just a launch strategy but a way of running an ongoing organization'),
  ('book-the-lean-startup-sec9-s2', 'book-the-lean-startup-sec9', 2, 'Ries argues large companies can use these same methods to keep innovating internally'),
