  ('book-the-lean-startup-sec9-s5', 'book-the-lean-startup-sec9', 5, 'The book closes by urging every team large or small to treat uncertainty as something to test not guess'),
  ('book-steve-jobs-sec1-s1', 'book-steve-jobs-sec1', 1, 'Steve Jobs was given up for adoption at birth and raised by Paul and Clara Jobs in California'),
